<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';admin_required();
if(is_post()){
    verify_csrf();$action=scalar_string($_POST['action']??'');
    try{
        if($action==='settings'){$enabled=isset($_POST['backup_enabled'])?'1':'0';$uploads=isset($_POST['backup_include_uploads'])?'1':'0';$hours=max(1,min(168,scalar_int($_POST['backup_interval_hours']??24,24)));$keep=max(1,min(50,scalar_int($_POST['backup_retention_count']??7,7)));$stmt=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach(['backup_enabled'=>$enabled,'backup_include_uploads'=>$uploads,'backup_interval_hours'=>(string)$hours,'backup_retention_count'=>(string)$keep] as $key=>$value)$stmt->execute([$key,$value]);admin_audit_event('backup_settings_saved');flash('success','تنظیمات بکاپ ذخیره شد.');}
        elseif($action==='create'){$result=create_store_backup('manual',(int)(admin_user()['id']??0));flash('success','بکاپ با موفقیت ساخته شد: '.$result['file_name']);}
        elseif($action==='delete'){$id=max(1,scalar_int($_POST['id']??0));$stmt=db()->prepare("SELECT file_name FROM backup_runs WHERE id=? AND status='completed'");$stmt->execute([$id]);$name=(string)$stmt->fetchColumn();if($name===''||basename($name)!==$name)throw new RuntimeException('فایل بکاپ پیدا نشد.');$path=backup_directory().'/'.$name;if(is_file($path)&&!unlink($path))throw new RuntimeException('حذف فایل بکاپ انجام نشد.');db()->prepare('DELETE FROM backup_runs WHERE id=?')->execute([$id]);admin_audit_event('backup_deleted','backup',$id,['file_name'=>$name]);flash('success','فایل بکاپ حذف شد.');}
    }catch(Throwable $error){log_error($error);flash('error',$error->getMessage());}
    redirect(app_url('admin/backups.php'));
}
$runs=db()->query('SELECT b.*,a.full_name admin_name FROM backup_runs b LEFT JOIN admins a ON a.id=b.admin_id ORDER BY b.id DESC LIMIT 100')->fetchAll();$centralCronCommand=central_cron_cli_command('/usr/local/bin/php');$adminPage='backups';$adminTitle='بکاپ خودکار';require __DIR__.'/partials/header.php';
?>
